recipes.code:
{
  "inputs": [
    {
      "id": "kodiak-api-key",
      "type": "promptString",
      "description": "Kodiak API key as a Bearer token. Get one at https://azurecarbon.com",
      "password": true
    }
  ],
  "servers": {
    "kodiak": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "kodiak-mcp@0.1.2"
      ],
      "env": {
        "KODIAK_API_KEY": "${input:kodiak-api-key}",
        "KODIAK_URL": "<kodiak-url>"
      }
    }
  }
}
